package com.example.ai_service.advisor;

import com.example.ai_service.conversation.ChatModels.PolicyInfo;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.io.ClassPathResource;
import org.springframework.stereotype.Component;
import java.text.Normalizer;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Optional;

/** Reviewed source text, never generated by the LLM. Approval is a local config, not a chat instruction. */
@Component
public class PolicyCatalog {
    public static final String VERSION="2026-10-26-v4";
    private static final int EXPECTED_ENTRIES=18;
    private static final List<String> STATUSES=List.of("SUPPORTED","PARTIAL","NOT_IMPLEMENTED");
    /** Demo mailbox; deployments override it with {@code app.ai.support-email}. */
    public static final String DEMO_SUPPORT_EMAIL="danhcong6205@gmail.com";

    public record Entry(String key,String title,String status,List<String> keywords,String text) {}
    public record Source(String version,String sourceLabel,String effectiveDate,String scope,List<Entry> entries) {}
    public record Answer(String text,PolicyInfo info) {}
    private final Source source;
    private final boolean approved;
    private final String supportEmail;
    public PolicyCatalog(ObjectMapper mapper,@Value("${app.ai.faq-approved-version:}") String approvedVersion,
            @Value("${app.ai.support-email:" + DEMO_SUPPORT_EMAIL + "}") String supportEmail) {
        this.supportEmail = supportEmail;
        if (supportEmail.isBlank()) throw new IllegalStateException("Support contact email is required.");
        try(var stream=new ClassPathResource("ai/policies-v2.json").getInputStream()) {
            source=mapper.readValue(stream,Source.class);
            if(!VERSION.equals(source.version()) || source.sourceLabel()==null || source.scope()==null || source.effectiveDate()==null
                    || source.entries()==null || source.entries().size()!=EXPECTED_ENTRIES
                    || source.entries().stream().anyMatch(e->e.key()==null || e.title()==null || e.keywords()==null || e.keywords().isEmpty()
                        || !STATUSES.contains(e.status())
                        || e.text()==null || e.text().isBlank() || e.text().length()>1600)
                    || source.entries().stream().map(Entry::key).distinct().count()!=EXPECTED_ENTRIES)
                throw new IllegalStateException("Invalid FAQ source.");
        } catch(Exception failure) { throw new IllegalStateException("Cannot load versioned FAQ source."); }
        approved=source.version().equals(approvedVersion);
        if(!approved && approvedVersion!=null && !approvedVersion.isBlank())
            throw new IllegalStateException("FAQ approval version does not match source.");
    }
    public Optional<Source> published() { return approved?Optional.of(source):Optional.empty(); }
    public PolicyInfo info(String key) { return new PolicyInfo(key,source.version(),source.sourceLabel()); }
    public static String normalize(String text) {
        return Normalizer.normalize(text,Normalizer.Form.NFD).replaceAll("\\p{M}","")
                .replace('đ','d').replace('Đ','D').toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+"," ").strip();
    }
    public static boolean isPolicyQuestion(String question) {
        return contains(normalize(question),"chinh sach","quy dinh","dieu khoan","faq","giu cho bao lau","giu slot",
                "han thanh toan","hoan tien","phi huy","bao hiem","visa","huy tour nhu the nao","co nhac lich khong",
                "co email nhac","doi tour duoc khong","doi ngay duoc khong","gui danh gia","viet danh gia","viet review","duoc danh gia");
    }
    public Optional<Answer> answer(String question) {
        if(!approved) return Optional.empty();
        String text=normalize(question);
        if(contains(text,"chinh sach chung","tat ca chinh sach","danh sach chinh sach","faq"))
            return Optional.of(new Answer("Bạn xem toàn bộ chính sách tại mục Chính sách trên website. Nội dung gồm giữ chỗ, thanh toán, hủy, giá, nhóm tuổi, nhắc lịch và các chức năng chưa hỗ trợ.",info("INDEX")));
        Entry selected=null; int best=0;
        for(var entry:source.entries()) for(String keyword:entry.keywords()) {
            String phrase=normalize(keyword);
            if(contains(text,phrase) && phrase.length()>best) { selected=entry;best=phrase.length(); }
        }
        if(selected==null) return Optional.of(new Answer("Hiện chưa có chính sách này trong SGU Tour. Bạn có thể xem mục Chính sách hoặc liên hệ "
                +supportEmail+" để được làm rõ; tôi không tự đặt điều kiện hoặc mức phí.",info("P18")));
        return Optional.of(new Answer(selected.text(),info(selected.key())));
    }
    private static boolean contains(String text,String... words) { return Arrays.stream(words).anyMatch(word->(" "+text+" ").contains(" "+word+" ")); }
}
